<div class="page-heading split"><div><p class="eyebrow">Restricted area</p><h1>Administration</h1><p class="muted">Accounts, daily access codes, audit activity and delivery limits.</p></div><span class="badge badge-admin">Administrator</span></div>
<?php if(!empty($issuedCode)): ?><div class="notice notice-success"><strong>New code (shown once):</strong> <code class="mono code-reveal"><?= e($issuedCode) ?></code><br>Copy it now and give it only to the assigned account owner. It expires at the end of the configured local day and can be revoked at any time.</div><?php endif; ?>
<section class="panel section-block" id="accounts"><div class="section-heading"><div><h2>User accounts</h2><p class="muted">Suspend access, set daily limits, or manage administrator roles.</p></div></div>
<div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Daily limit</th><th>Timezone</th><th><span class="sr-only">Manage</span></th></tr></thead><tbody><?php foreach($users as $account): ?><tr><td><?= e($account['name']) ?><br><span class="muted small"><?= e($account['email']) ?></span></td><td><?= e(ucfirst($account['role'])) ?></td><td><span class="badge badge-<?= e($account['status']) ?>"><?= e(ucfirst($account['status'])) ?></span></td><td><?= number_format((int)$account['daily_limit']) ?></td><td class="small"><?= e($account['timezone']) ?></td><td><details class="row-menu"><summary>Manage</summary><div class="menu-content"><form method="post" action="<?= e(url('admin/user')) ?>" class="stack compact"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><label for="limit-<?= (int)$account['id'] ?>">Daily limit</label><input id="limit-<?= (int)$account['id'] ?>" type="number" min="0" max="100000" name="daily_limit" value="<?= (int)$account['daily_limit'] ?>"><label for="role-<?= (int)$account['id'] ?>">Role</label><select id="role-<?= (int)$account['id'] ?>" name="role"><option value="operator" <?= $account['role']==='operator'?'selected':'' ?>>Operator</option><option value="admin" <?= $account['role']==='admin'?'selected':'' ?>>Administrator</option></select><label for="status-<?= (int)$account['id'] ?>">Status</label><select id="status-<?= (int)$account['id'] ?>" name="status"><option value="active" <?= $account['status']==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $account['status']==='suspended'?'selected':'' ?>>Suspended</option></select><button class="button button-small button-secondary" type="submit">Save account</button></form><?php if((int)$account['id']!==(int)$user['id']): ?><form method="post" action="<?= e(url('admin/user/delete')) ?>" data-confirm="Permanently delete this account and all its contacts, templates and campaigns? This cannot be undone."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><button class="link-button danger" type="submit">Delete account</button></form><?php endif; ?></div></details></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="two-col section-block"><section class="panel"><h2>Issue an access code</h2><form method="post" action="<?= e(url('admin/code')) ?>" class="stack"><?= csrf_field() ?><label for="code-label">Label</label><input id="code-label" name="label" required maxlength="120" placeholder="e.g. Daily code — Monday"><fieldset><legend>Assign to accounts</legend><div class="checkbox-list scroll-list"><?php foreach($users as $account): ?><?php if($account['status']==='active'): ?><label class="check"><input type="checkbox" name="account_ids[]" value="<?= (int)$account['id'] ?>"> <?= e($account['name']) ?> <span class="muted small"><?= e($account['email']) ?></span></label><?php endif; ?><?php endforeach; ?></div></fieldset><p class="hint">Codes are single-use for each assigned active account, expire at the end of the current local day, and are stored hashed.</p><button class="button" type="submit">Generate code</button></form></section>
<section class="panel"><h2>Access codes</h2><?php if(!$codes): ?><p class="muted">No codes issued yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Label</th><th>Accounts</th><th>Expires</th><th>Status</th><th><span class="sr-only">Action</span></th></tr></thead><tbody><?php foreach($codes as $codeRow): ?><tr><td><?= e($codeRow['label']) ?><br><span class="muted small">Issued <?= e(date('M j, H:i',strtotime($codeRow['created_at']))) ?> UTC</span></td><td><?= (int)$codeRow['account_count'] ?></td><td class="small"><?= e(date('M j, H:i',strtotime($codeRow['expires_at']))) ?> UTC</td><td><span class="badge badge-<?= $codeRow['revoked_at']?'cancelled':(strtotime($codeRow['expires_at'])<time()?'failed':'active') ?>"><?= $codeRow['revoked_at']?'Revoked':(strtotime($codeRow['expires_at'])<time()?'Expired':'Active') ?></span></td><td><?php if(!$codeRow['revoked_at']&&strtotime($codeRow['expires_at'])>=time()): ?><form method="post" action="<?= e(url('admin/code/revoke')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$codeRow['id'] ?>"><button class="link-button danger" type="submit">Revoke</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<section class="panel section-block" id="audit"><h2>Audit log</h2><p class="muted">Privileged actions, most recent first. Sensitive values are not recorded.</p><?php if(!$audit): ?><p class="muted">No audit entries yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody><?php foreach($audit as $entry): ?><tr><td class="small mono"><?= e($entry['created_at']) ?> UTC</td><td><?= e($entry['actor_name']?'User #'.$entry['actor_id']:'System') ?></td><td><code><?= e($entry['action']) ?></code></td><td><span class="small"><?= e($entry['target_type']) ?> #<?= e($entry['target_id']) ?></span></td><td class="small muted"><?= e(mb_substr((string)$entry['metadata_json'],0,180)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
